`timescale 1ns/1ps
// Architectural flags change at WB under independent masks. Address ADD,
// MOV, AND/OR and branches preserve flags through zero write masks.
module flags_reg(
    input clk, rst, z_we, cv_we, z_in, c_in, v_in,
    output reg Z, C, V
);
    always @(posedge clk) begin
        if (rst) begin
            Z <= 1'b0;
            C <= 1'b0;
            V <= 1'b0;
        end else begin
            if (z_we) Z <= z_in;
            if (cv_we) begin
                C <= c_in;
                V <= v_in;
            end
        end
    end
endmodule

reg z_effective;
reg [1:0] z_fwd_sel;
always @* begin
    z_effective = Z;
    z_fwd_sel = 2'd0;
    if (m_valid && !m_fault && m_z_write) begin
        z_effective = m_cmp_z;
        z_fwd_sel = 2'd1;
    end else if (w_valid && !w_fault && w_z_write) begin
        z_effective = w_cmp_z;
        z_fwd_sel = 2'd2;
